#!/usr/bin/env python3
from __future__ import annotations

import argparse
import importlib.util
import json
from pathlib import Path

from hls_bench import config


REPO_ROOT = Path(__file__).resolve().parents[1]
OPENHLS_DB = config.OPENHLS_ROOT / "library" / "database"
EXPORT_SCRIPT = OPENHLS_DB / "export_artix7_scheduler_timing.py"
IR_JSON = OPENHLS_DB / "artix7_ir.json"
BASE_JSON = OPENHLS_DB / "artix7_timing.json"

# Latencies of the single-precision Xilinx Floating Point IP cores generated by
# legup_vivado_flow.sh. LegUp encodes the scheduled latency in module names.
XILINX_FP_LATENCIES = {
    "altfp_add": 8,
    "altfp_subtract": 8,
    "altfp_multiply": 4,
    # LegUp's non-pipelined fdiv emitter requires altfp_divider_33. The
    # adapter adds five output registers to the 28-cycle Xilinx divider.
    "altfp_divide": 33,
    "altfp_sitofp": 7,
}


def load_module(path: Path):
    spec = importlib.util.spec_from_file_location(path.stem, path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"unable to load module from {path}")
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def load_json(path: Path):
    return json.loads(path.read_text())


def resource_amount(entry: dict, kind: str) -> int:
    total = 0
    resources = entry.get("resources")
    if isinstance(resources, list):
        for item in resources:
            if not isinstance(item, dict):
                continue
            if str(item.get("resource")) == kind:
                try:
                    total += int(item.get("amount", 0))
                except (TypeError, ValueError):
                    pass
    elif isinstance(resources, dict):
        try:
            total = int(resources.get(kind, 0))
        except (TypeError, ValueError):
            total = 0
    return total


def attr_line(name: str, entry: dict, latency_override: int | None = None) -> str:
    timing = entry.get("timing") if isinstance(entry.get("timing"), dict) else entry
    delay = float(timing.get("delay_ns", 0.0) or 0.0)
    latency = latency_override if latency_override is not None else int(timing.get("latency_cycles", 0) or 0)
    fmax = 1000.0 / delay if delay > 0 else 1000.0
    lut = resource_amount(entry, "lut")
    reg = resource_amount(entry, "ff")
    dsp = resource_amount(entry, "dsp")
    le = lut
    return (
        f'set_operation_attributes -Name {name} -Fmax {fmax:.3f} -CritDelay {delay:.3f} '
        f'-StaticPower 0.0 -DynamicPower 0.0 -LUTs {lut} -Registers {reg} -LEs {le} -DSP {dsp} -Latency {latency}'
    )


def latency_line(name: str, entry: dict) -> str:
    timing = entry.get("timing") if isinstance(entry.get("timing"), dict) else entry
    latency = int(timing.get("latency_cycles", 0) or 0)
    return f"set_operation_latency {name} {latency}"


def choose_ops(mod, width: int, target_clock_ns: float) -> dict[str, dict]:
    ir = load_json(IR_JSON)
    base = load_json(BASE_JSON)
    return mod.build_scheduler_timing(
        ir,
        base,
        preferred_width=width,
        preferred_mux_inputs=2,
        target_clock_ns=target_clock_ns,
    )["op_types"]


def first_or_none(ops: dict[str, dict], key: str):
    return ops.get(key)


def build_text(clock_period: float) -> str:
    mod = load_module(EXPORT_SCRIPT)

    ops8 = choose_ops(mod, 8, clock_period)
    ops16 = choose_ops(mod, 16, clock_period)
    ops32 = choose_ops(mod, 32, clock_period)
    ops64 = choose_ops(mod, 64, clock_period)

    lines = [
        "# Auto-generated from OpenHLS Artix-7 timing databases",
        f"set_parameter CLOCK_PERIOD {clock_period:g}",
        "# Pipeline every eligible loop in LegUp without forcing an II or ignoring memory dependencies.",
        "set_parameter PIPELINE_ALL 1",
        "",
    ]

    # Generic latency families used by LegUp's longest-prefix matching.
    generic_latencies = {
        "mem_dual_port": first_or_none(ops32, "load"),
        "local_mem_dual_port": first_or_none(ops32, "load"),
        "reg": first_or_none(ops32, "default_op"),
        "signed_add": first_or_none(ops32, "add"),
        "unsigned_add": first_or_none(ops32, "add"),
        "signed_subtract": first_or_none(ops32, "sub"),
        "unsigned_subtract": first_or_none(ops32, "sub"),
        "signed_multiply": first_or_none(ops32, "mul"),
        "unsigned_multiply": first_or_none(ops32, "mul"),
        "signed_divide": first_or_none(ops32, "sdiv"),
        "unsigned_divide": first_or_none(ops32, "udiv"),
        "signed_modulus": first_or_none(ops32, "srem"),
        "unsigned_modulus": first_or_none(ops32, "urem"),
        "bitwise_AND": first_or_none(ops32, "and"),
        "bitwise_OR": first_or_none(ops32, "or"),
        "bitwise_XOR": first_or_none(ops32, "xor"),
        "shift_ll": first_or_none(ops32, "shl"),
        "shift_ra": first_or_none(ops32, "ashr"),
        "shift_rl": first_or_none(ops32, "lshr"),
        "signed_comp_eq": first_or_none(ops32, "icmp"),
        "signed_comp_lt": first_or_none(ops32, "icmp"),
        "signed_comp_lte": first_or_none(ops32, "icmp"),
        "signed_comp_gt": first_or_none(ops32, "icmp"),
        "signed_comp_gte": first_or_none(ops32, "icmp"),
        "unsigned_comp_eq": first_or_none(ops32, "icmp"),
        "unsigned_comp_lt": first_or_none(ops32, "icmp"),
        "unsigned_comp_lte": first_or_none(ops32, "icmp"),
        "unsigned_comp_gt": first_or_none(ops32, "icmp"),
        "unsigned_comp_gte": first_or_none(ops32, "icmp"),
        "signed_comp_eq_mux": first_or_none(ops32, "select"),
        "altfp_add": first_or_none(ops32, "fadd"),
        "altfp_subtract": first_or_none(ops32, "fsub"),
        "altfp_multiply": first_or_none(ops32, "fmul"),
        "altfp_divide": first_or_none(ops32, "fdiv"),
        "altfp_extend": first_or_none(ops32, "fpext"),
        "altfp_truncate": first_or_none(ops32, "fptrunc"),
        "altfp_fptosi": first_or_none(ops32, "fptosi"),
        "altfp_sitofp": first_or_none(ops32, "sitofp"),
    }
    for name, entry in generic_latencies.items():
        if entry is not None:
            latency = XILINX_FP_LATENCIES.get(name)
            if latency is None:
                lines.append(latency_line(name, entry))
            else:
                lines.append(f"set_operation_latency {name} {latency}")

    lines.append("")

    def width_rows(width: int, ops: dict[str, dict]) -> list[str]:
        out: list[str] = []

        def emit(op_name: str, entry: dict | None, latency_override: int | None = None):
            if entry is None:
                return
            out.append(attr_line(op_name, entry, latency_override))

        for base_name in ("add", "sub", "mul", "sdiv", "udiv", "srem", "urem", "and", "or", "xor", "shl", "ashr", "lshr"):
            entry = first_or_none(ops, base_name)
            if entry is None:
                continue
            if base_name == "add":
                emit(f"signed_add_{width}", entry)
                emit(f"unsigned_add_{width}", entry)
            elif base_name == "sub":
                emit(f"signed_subtract_{width}", entry)
                emit(f"unsigned_subtract_{width}", entry)
            elif base_name == "mul":
                emit(f"signed_multiply_{width}", entry)
                emit(f"unsigned_multiply_{width}", entry)
            elif base_name == "sdiv":
                emit(f"signed_divide_{width}", entry)
            elif base_name == "udiv":
                emit(f"unsigned_divide_{width}", entry)
            elif base_name == "srem":
                emit(f"signed_modulus_{width}", entry)
            elif base_name == "urem":
                emit(f"unsigned_modulus_{width}", entry)
            elif base_name == "and":
                emit(f"bitwise_AND_{width}", entry)
            elif base_name == "or":
                emit(f"bitwise_OR_{width}", entry)
            elif base_name == "xor":
                emit(f"bitwise_XOR_{width}", entry)
            elif base_name == "shl":
                emit(f"shift_ll_{width}", entry)
            elif base_name == "ashr":
                emit(f"shift_ra_{width}", entry)
            elif base_name == "lshr":
                emit(f"shift_rl_{width}", entry)

        cmp_entry = first_or_none(ops, "icmp")
        if cmp_entry is not None:
            for pred in ("eq", "lt", "lte", "gt", "gte"):
                emit(f"signed_comp_{pred}_{width}", cmp_entry)
                emit(f"unsigned_comp_{pred}_{width}", cmp_entry)

        fcmp_entry = first_or_none(ops, "fcmp")
        if fcmp_entry is not None:
            for pred in ("oeq", "ueq", "one", "une", "olt", "ult", "ole", "ule", "ogt", "ugt", "oge", "uge"):
                emit(f"signed_comp_{pred}_{width}", fcmp_entry)

        sel_entry = first_or_none(ops, "select")
        if sel_entry is not None:
            emit(f"signed_comp_eq_mux_{width}", sel_entry)

        for op_key, legup_prefix in (("fadd", "altfp_add"), ("fsub", "altfp_subtract"), ("fmul", "altfp_multiply"), ("fdiv", "altfp_divide")):
            entry = first_or_none(ops, op_key)
            if entry is None:
                continue
            emit(f"{legup_prefix}_{width}", entry, XILINX_FP_LATENCIES[legup_prefix])

        entry = first_or_none(ops, "fpext")
        if entry is not None and width in (32, 64):
            emit(f"altfp_extend_{width}", entry)

        entry = first_or_none(ops, "fptrunc")
        if entry is not None and width == 64:
            emit("altfp_truncate_64", entry)

        entry = first_or_none(ops, "fptosi")
        if entry is not None and width in (32, 64):
            emit(f"altfp_fptosi_{width}", entry)

        entry = first_or_none(ops, "sitofp")
        if entry is not None and width in (32, 64):
            emit(f"altfp_sitofp_{width}", entry, XILINX_FP_LATENCIES["altfp_sitofp"])

        return out

    for width, ops in ((8, ops8), (16, ops16), (32, ops32), (64, ops64)):
        lines.extend(width_rows(width, ops))
        lines.append("")

    # Memory and register-like resources.
    load_entry = first_or_none(ops32, "load")
    store_entry = first_or_none(ops32, "store") or load_entry
    if load_entry is not None:
        lines.append(attr_line("mem_dual_port", load_entry))
        lines.append(attr_line("local_mem_dual_port", load_entry))
    if store_entry is not None:
        lines.append(attr_line("store", store_entry))
    reg_entry = first_or_none(ops32, "default_op")
    if reg_entry is not None:
        for width in (8, 16, 32, 64):
            lines.append(attr_line(f"reg_{width}", reg_entry))

    return "\n".join(lines) + "\n"


def main() -> None:
    ap = argparse.ArgumentParser(description="Generate a LegUp config.tcl from OpenHLS Artix-7 timing data")
    ap.add_argument("--output", required=True, help="Output config.tcl path")
    ap.add_argument("--period", type=float, default=10.0, help="Target clock period in ns")
    args = ap.parse_args()
    Path(args.output).write_text(build_text(args.period))


if __name__ == "__main__":
    main()
